#!/usr/bin/env node
// FYP.STUDIO — Sistema de Verticales
// node setup_verticals.js (desde raíz del proyecto)
const fs = require('fs'), path = require('path')
const files = {}

files["lib/verticals.ts"] = "// lib/verticals.ts\n// ============================================================\n// FYP.STUDIO — Sistema de Verticales\n// Un solo core, múltiples rubros\n// ============================================================\n\nexport type VerticalType =\n  | 'food'\n  | 'real_estate'\n  | 'fashion'\n  | 'beauty'\n  | 'barbershop'\n  | 'services'\n  | 'general'\n\n// ── Módulos disponibles en el sistema ────────────────────────\nexport type ModuleKey =\n  | 'orders'\n  | 'products'\n  | 'inventory'\n  | 'suppliers'\n  | 'categories'\n  | 'customers'\n  | 'ai'\n  | 'settings'\n  | 'kitchen'       // food\n  | 'delivery'      // food\n  | 'combos'        // food\n  | 'schedule'      // food / beauty / barbershop\n  | 'properties'    // real_estate\n  | 'leads'         // real_estate / services\n  | 'brokers'       // real_estate\n  | 'visits'        // real_estate\n  | 'variants'      // fashion\n  | 'drops'         // fashion\n  | 'appointments'  // beauty / barbershop\n  | 'staff'         // beauty / barbershop\n  | 'services_cat'  // services / beauty / barbershop\n  | 'tasks'         // services\n\n// ── KPIs por vertical ────────────────────────────────────────\nexport type KPIKey =\n  | 'revenue'\n  | 'orders'\n  | 'customers'\n  | 'products'\n  | 'pending_orders'\n  | 'conversion'\n  | 'leads'\n  | 'properties'\n  | 'appointments'\n  | 'avg_ticket'\n  | 'stock_alerts'\n\n// ── Configuración de un módulo ────────────────────────────────\nexport interface ModuleConfig {\n  key: ModuleKey\n  label: string\n  icon: string            // lucide icon name\n  href: string\n  description: string\n  required: boolean       // no se puede desactivar\n}\n\n// ── Widget del dashboard ──────────────────────────────────────\nexport interface DashboardWidget {\n  key: KPIKey\n  label: string\n  description: string\n  size: 'sm' | 'md' | 'lg'  // sm=1col, md=2col, lg=full\n}\n\n// ── Configuración completa de un vertical ─────────────────────\nexport interface VerticalConfig {\n  key: VerticalType\n  label: string\n  emoji: string\n  description: string\n  color: string           // color primario del vertical\n  accentColor: string     // color secundario\n  examples: string[]      // ejemplos de negocios\n  modules: ModuleKey[]    // módulos habilitados (en orden de nav)\n  requiredModules: ModuleKey[]\n  dashboardWidgets: KPIKey[]\n  storeType: 'catalog' | 'menu' | 'properties' | 'services' | 'appointments'\n  checkoutType: 'whatsapp' | 'booking' | 'lead' | 'contact'\n  productLabel: string    // \"Producto\", \"Plato\", \"Propiedad\", \"Servicio\"\n  orderLabel: string      // \"Pedido\", \"Turno\", \"Reserva\", \"Lead\"\n  categoryLabel: string   // \"Categoría\", \"Sección\", \"Tipo\", \"Zona\"\n  features: {\n    hasDelivery: boolean\n    hasPickup: boolean\n    hasBooking: boolean\n    hasVariants: boolean\n    hasStock: boolean\n    hasSchedule: boolean\n    hasMap: boolean\n    hasCRM: boolean\n  }\n}\n\n// ────────────────────────────────────────────────────────────\n// DEFINICIÓN DE VERTICALES\n// ────────────────────────────────────────────────────────────\n\nexport const VERTICALS: Record<VerticalType, VerticalConfig> = {\n\n  // ── FOOD ──────────────────────────────────────────────────\n  food: {\n    key: 'food',\n    label: 'Gastronomía',\n    emoji: '🍔',\n    description: 'Restaurantes, cafeterías, delivery, dark kitchens',\n    color: '#FF5722',\n    accentColor: '#FFF3E0',\n    examples: ['Hamburguesería', 'Cafetería', 'Pizzería', 'Panadería', 'Dark Kitchen'],\n    modules: ['orders','products','categories','inventory','suppliers','customers','ai','settings'],\n    requiredModules: ['orders','products','settings'],\n    dashboardWidgets: ['pending_orders','revenue','orders','customers','avg_ticket','conversion'],\n    storeType: 'menu',\n    checkoutType: 'whatsapp',\n    productLabel: 'Plato',\n    orderLabel: 'Pedido',\n    categoryLabel: 'Sección',\n    features: {\n      hasDelivery: true, hasPickup: true, hasBooking: false,\n      hasVariants: false, hasStock: true, hasSchedule: true,\n      hasMap: false, hasCRM: false,\n    },\n  },\n\n  // ── REAL ESTATE ───────────────────────────────────────────\n  real_estate: {\n    key: 'real_estate',\n    label: 'Inmobiliaria',\n    emoji: '🏠',\n    description: 'Inmobiliarias, brokers, alquileres, ventas',\n    color: '#1565FF',\n    accentColor: '#EFF6FF',\n    examples: ['Inmobiliaria', 'Broker independiente', 'Alquiler temporario'],\n    modules: ['products','categories','leads','customers','ai','settings'],\n    requiredModules: ['products','settings'],\n    dashboardWidgets: ['leads','properties','customers','revenue','conversion'],\n    storeType: 'properties',\n    checkoutType: 'lead',\n    productLabel: 'Propiedad',\n    orderLabel: 'Consulta',\n    categoryLabel: 'Zona',\n    features: {\n      hasDelivery: false, hasPickup: false, hasBooking: true,\n      hasVariants: false, hasStock: false, hasSchedule: false,\n      hasMap: true, hasCRM: true,\n    },\n  },\n\n  // ── FASHION ───────────────────────────────────────────────\n  fashion: {\n    key: 'fashion',\n    label: 'Moda & Ropa',\n    emoji: '👕',\n    description: 'Tiendas de ropa, streetwear, accesorios, calzado',\n    color: '#7C3AED',\n    accentColor: '#F5F3FF',\n    examples: ['Streetwear', 'Boutique', 'Tienda de calzado', 'Accesorios'],\n    modules: ['products','categories','inventory','orders','customers','ai','settings'],\n    requiredModules: ['products','orders','settings'],\n    dashboardWidgets: ['revenue','orders','customers','products','stock_alerts','conversion'],\n    storeType: 'catalog',\n    checkoutType: 'whatsapp',\n    productLabel: 'Producto',\n    orderLabel: 'Pedido',\n    categoryLabel: 'Categoría',\n    features: {\n      hasDelivery: true, hasPickup: true, hasBooking: false,\n      hasVariants: true, hasStock: true, hasSchedule: false,\n      hasMap: false, hasCRM: false,\n    },\n  },\n\n  // ── BEAUTY ────────────────────────────────────────────────\n  beauty: {\n    key: 'beauty',\n    label: 'Belleza & Spa',\n    emoji: '💅',\n    description: 'Salones, spas, estética, peluquerías',\n    color: '#EC4899',\n    accentColor: '#FDF2F8',\n    examples: ['Salón de belleza', 'Spa', 'Centro de estética', 'Manicura'],\n    modules: ['products','categories','customers','orders','ai','settings'],\n    requiredModules: ['products','settings'],\n    dashboardWidgets: ['appointments','revenue','customers','products','conversion'],\n    storeType: 'services',\n    checkoutType: 'booking',\n    productLabel: 'Servicio',\n    orderLabel: 'Turno',\n    categoryLabel: 'Tipo de servicio',\n    features: {\n      hasDelivery: false, hasPickup: false, hasBooking: true,\n      hasVariants: false, hasStock: false, hasSchedule: true,\n      hasMap: false, hasCRM: true,\n    },\n  },\n\n  // ── BARBERSHOP ────────────────────────────────────────────\n  barbershop: {\n    key: 'barbershop',\n    label: 'Barbería',\n    emoji: '✂️',\n    description: 'Barberías, peluquerías masculinas, grooming',\n    color: '#0B3EAB',\n    accentColor: '#EFF6FF',\n    examples: ['Barbería', 'Peluquería masculina', 'Grooming center'],\n    modules: ['products','categories','customers','orders','ai','settings'],\n    requiredModules: ['products','settings'],\n    dashboardWidgets: ['appointments','revenue','customers','conversion'],\n    storeType: 'appointments',\n    checkoutType: 'booking',\n    productLabel: 'Servicio',\n    orderLabel: 'Turno',\n    categoryLabel: 'Tipo de corte',\n    features: {\n      hasDelivery: false, hasPickup: false, hasBooking: true,\n      hasVariants: false, hasStock: false, hasSchedule: true,\n      hasMap: false, hasCRM: true,\n    },\n  },\n\n  // ── SERVICES ──────────────────────────────────────────────\n  services: {\n    key: 'services',\n    label: 'Servicios',\n    emoji: '🔧',\n    description: 'Plomería, electricidad, diseño, consultoría, freelance',\n    color: '#059669',\n    accentColor: '#ECFDF5',\n    examples: ['Plomero', 'Electricista', 'Diseñador', 'Consultor', 'Fotógrafo'],\n    modules: ['products','categories','customers','orders','ai','settings'],\n    requiredModules: ['products','settings'],\n    dashboardWidgets: ['leads','revenue','customers','orders','conversion'],\n    storeType: 'services',\n    checkoutType: 'contact',\n    productLabel: 'Servicio',\n    orderLabel: 'Solicitud',\n    categoryLabel: 'Tipo de servicio',\n    features: {\n      hasDelivery: false, hasPickup: false, hasBooking: true,\n      hasVariants: false, hasStock: false, hasSchedule: false,\n      hasMap: false, hasCRM: true,\n    },\n  },\n\n  // ── GENERAL ───────────────────────────────────────────────\n  general: {\n    key: 'general',\n    label: 'General',\n    emoji: '🏪',\n    description: 'Cualquier negocio. Flexible y personalizable',\n    color: '#374151',\n    accentColor: '#F9FAFB',\n    examples: ['Minimarket', 'Ferretería', 'Librería', 'Cualquier comercio'],\n    modules: ['orders','products','categories','inventory','suppliers','customers','ai','settings'],\n    requiredModules: ['settings'],\n    dashboardWidgets: ['revenue','orders','customers','products','conversion'],\n    storeType: 'catalog',\n    checkoutType: 'whatsapp',\n    productLabel: 'Producto',\n    orderLabel: 'Pedido',\n    categoryLabel: 'Categoría',\n    features: {\n      hasDelivery: true, hasPickup: true, hasBooking: false,\n      hasVariants: false, hasStock: true, hasSchedule: false,\n      hasMap: false, hasCRM: false,\n    },\n  },\n}\n\n// ────────────────────────────────────────────────────────────\n// HELPERS\n// ────────────────────────────────────────────────────────────\n\n// Obtener config del vertical (con fallback a general)\nexport function getVertical(type?: string | null): VerticalConfig {\n  if (type && type in VERTICALS) return VERTICALS[type as VerticalType]\n  return VERTICALS.general\n}\n\n// Verificar si un módulo está habilitado para un vertical\nexport function isModuleEnabled(vertical: VerticalType, module: ModuleKey): boolean {\n  return VERTICALS[vertical].modules.includes(module)\n}\n\n// Obtener nav items filtrados por vertical\nexport function getNavItems(vertical: VerticalType) {\n  const config = getVertical(vertical)\n  const ALL_NAV = [\n    { key: 'orders' as ModuleKey,     label: config.orderLabel + 's',   icon: 'ShoppingBag', href: '/admin/orders',     exact: false },\n    { key: 'products' as ModuleKey,   label: config.productLabel + 's', icon: 'Package',     href: '/admin/products',   exact: false },\n    { key: 'inventory' as ModuleKey,  label: 'Inventario',              icon: 'Layers',      href: '/admin/inventory',  exact: false },\n    { key: 'suppliers' as ModuleKey,  label: 'Proveedores',             icon: 'Truck',       href: '/admin/suppliers',  exact: false },\n    { key: 'categories' as ModuleKey, label: config.categoryLabel + 's',icon: 'Tag',         href: '/admin/categories', exact: false },\n    { key: 'customers' as ModuleKey,  label: 'Clientes',                icon: 'Users',       href: '/admin/customers',  exact: false },\n    { key: 'leads' as ModuleKey,      label: 'Leads',                   icon: 'Target',      href: '/admin/leads',      exact: false },\n    { key: 'ai' as ModuleKey,         label: 'IA',                      icon: 'Sparkles',    href: '/admin/ai',         exact: false },\n    { key: 'settings' as ModuleKey,   label: 'Configuración',           icon: 'Settings',    href: '/admin/settings',   exact: false },\n  ]\n  return ALL_NAV.filter(item => config.modules.includes(item.key))\n}\n\n// Lista de todos los verticales para el onboarding\nexport const VERTICAL_LIST = Object.values(VERTICALS)\n"

files["types/index.ts"] = "export type Plan = 'basic' | 'pro' | 'premium'\nexport type SubscriptionStatus = 'trial' | 'active' | 'past_due' | 'canceled' | 'suspended'\nexport type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\nexport type PaymentStatus = 'unpaid' | 'paid' | 'refunded'\nexport type DeliveryType = 'delivery' | 'pickup'\nexport type UserRole = 'owner' | 'staff' | 'superadmin'\nexport type AIGenerationType = 'product' | 'promo' | 'insights'\n\nexport interface Business {\n  id: string; name: string; slug: string; description?: string | null\n  logo_url?: string | null; banner_url?: string | null; whatsapp?: string | null\n  address?: string | null; currency: string; primary_color: string\n  secondary_color: string; plan: Plan; active: boolean\n  subscription_status: SubscriptionStatus; subscription_expires_at?: string | null\n  instagram?: string | null; facebook?: string | null; tiktok?: string | null\n  website?: string | null; vertical_type?: string | null; enabled_modules?: string[] | null; created_at: string; updated_at: string\n}\n\nexport interface Profile {\n  id: string; user_id: string; business_id: string\n  role: UserRole; created_at: string; business?: Business\n}\n\nexport interface Category {\n  id: string; business_id: string; name: string; slug: string\n  sort_order: number; active: boolean; created_at: string\n}\n\nexport interface Product {\n  id: string; business_id: string; category_id?: string | null\n  name: string; slug: string; description?: string | null; price: number\n  images: string[]; tags: string[]; stock?: number | null; featured: boolean\n  active: boolean; seo_title?: string | null; seo_desc?: string | null\n  created_at: string; updated_at: string; category?: Category | null\n}\n\nexport interface Customer {\n  id: string; business_id: string; name: string; phone?: string | null\n  address?: string | null; email?: string | null; total_orders: number\n  total_spent: number; created_at: string; updated_at: string\n}\n\nexport interface Order {\n  id: string; business_id: string; customer_id?: string | null\n  order_number: number; status: OrderStatus; payment_status: PaymentStatus\n  confirmed_sale: boolean; delivery_type: DeliveryType; subtotal: number\n  total: number; comment?: string | null; customer_name: string\n  customer_phone?: string | null; customer_address?: string | null\n  created_at: string; updated_at: string; items?: OrderItem[]; customer?: Customer | null\n}\n\nexport interface OrderItem {\n  id: string; order_id: string; product_id?: string | null\n  product_name: string; unit_price: number; quantity: number; subtotal: number\n  product?: Product | null\n}\n\nexport interface CartItem { product: Product; quantity: number }\n\nexport interface CheckoutFormData {\n  name: string; phone: string; address?: string\n  delivery_type: DeliveryType; comment?: string\n}\n\nexport interface CreateOrderResponse { orderId: string; orderNumber: number }\n\nexport interface AIProductOutput {\n  name: string; description: string; category: string; tags: string[]\n  instagram_copy: string; whatsapp_copy: string; hashtags: string[]\n  seo_title: string; seo_description: string\n}\n\nexport interface AIPromoOutput {\n  title: string; body: string; instagram_story: string\n  whatsapp_message: string; cta: string\n}\n\nexport interface DashboardStats {\n  pendingOrders: number; confirmedOrders: number; totalRevenue: number\n  todayRevenue: number; totalProducts: number; totalCustomers: number\n  recentOrders: Order[]; topProducts: { name: string; count: number; revenue: number }[]\n  cancelRate?: number\n}\n\n// ── Inventario ────────────────────────────────────────────────\n\nexport interface InventoryCategory {\n  id: string\n  business_id: string\n  name: string\n  color: string\n  icon: string\n  created_at: string\n}\n\nexport type MovementType = 'entrada' | 'salida' | 'ajuste' | 'devolucion'\n\nexport interface InventoryItem {\n  id: string\n  business_id: string\n  category_id?: string | null\n  product_id?: string | null\n  name: string\n  sku?: string | null\n  unit: string\n  stock_current: number\n  stock_min: number\n  stock_max?: number | null\n  cost_price?: number | null\n  supplier?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // joins\n  category?: InventoryCategory | null\n  product?: { name: string } | null\n}\n\nexport interface InventoryMovement {\n  id: string\n  business_id: string\n  item_id: string\n  order_id?: string | null\n  type: MovementType\n  quantity: number\n  stock_before: number\n  stock_after: number\n  reason?: string | null\n  created_by?: string | null\n  created_at: string\n  item?: InventoryItem | null\n}\n\nexport type StockStatus = 'ok' | 'low' | 'critical' | 'out'\n\nexport function getStockStatus(item: InventoryItem): StockStatus {\n  if (item.stock_current <= 0) return 'out'\n  if (item.stock_current <= item.stock_min * 0.5) return 'critical'\n  if (item.stock_current <= item.stock_min) return 'low'\n  return 'ok'\n}\n\n// ── Proveedores ───────────────────────────────────────────────\n\nexport interface Supplier {\n  id: string\n  business_id: string\n  name: string\n  contact_name?: string | null\n  phone?: string | null\n  email?: string | null\n  address?: string | null\n  city?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // computed\n  products?: SupplierProduct[]\n}\n\nexport interface SupplierProduct {\n  id: string\n  supplier_id: string\n  business_id: string\n  inventory_item_id?: string | null\n  product_name: string\n  sku_supplier?: string | null\n  unit: string\n  price?: number | null\n  min_order?: number | null\n  lead_days?: number | null\n  notes?: string | null\n  created_at: string\n  updated_at: string\n  // join\n  inventory_item?: { name: string } | null\n}\n"

files["supabase/migrations/004_verticals.sql"] = "-- ============================================================\n-- FYP.STUDIO — Migración: Sistema de Verticales\n-- Ejecutar en Supabase SQL Editor\n-- ============================================================\n\n-- Agregar vertical_type a businesses\nalter table businesses\n  add column if not exists vertical_type text\n    not null default 'general'\n    check (vertical_type in (\n      'food','real_estate','fashion','beauty',\n      'barbershop','services','general'\n    ));\n\n-- Agregar módulos habilitados (overrides del vertical)\nalter table businesses\n  add column if not exists enabled_modules text[] default null;\n  -- null = usar defaults del vertical\n  -- array = override manual\n\n-- Agregar configuración de widgets del dashboard\nalter table businesses\n  add column if not exists dashboard_config jsonb default null;\n  -- null = usar defaults del vertical\n\n-- Índice para filtrar por vertical\ncreate index if not exists idx_businesses_vertical\n  on businesses(vertical_type);\n\n-- Todos los negocios existentes → general\nupdate businesses\n  set vertical_type = 'general'\n  where vertical_type is null;\n\n-- ── Tabla de leads (para real_estate, services) ───────────────\ncreate table if not exists leads (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  name         text not null,\n  phone        text,\n  email        text,\n  message      text,\n  source       text default 'store',   -- store, whatsapp, form\n  status       text not null default 'new'\n                 check (status in ('new','contacted','qualified','closed','lost')),\n  product_id   uuid references products(id) on delete set null,\n  notes        text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index if not exists idx_leads_business on leads(business_id, status);\ncreate index if not exists idx_leads_created  on leads(business_id, created_at desc);\n\ncreate trigger set_updated_at_leads\n  before update on leads\n  for each row execute function update_updated_at();\n\nalter table leads enable row level security;\n\ncreate policy \"comercio gestiona leads\"\n  on leads for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\ncreate policy \"api puede insertar leads\"\n  on leads for insert with check (true);\n\n-- ── Tabla de turnos/appointments (beauty, barbershop) ────────\ncreate table if not exists appointments (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  customer_id  uuid references customers(id) on delete set null,\n  product_id   uuid references products(id) on delete set null,\n  customer_name text not null,\n  customer_phone text,\n  date         date not null,\n  time_slot    text not null,  -- '10:00', '10:30', etc.\n  duration_min int default 30,\n  status       text not null default 'pending'\n                 check (status in ('pending','confirmed','done','cancelled','noshow')),\n  notes        text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index if not exists idx_appointments_business on appointments(business_id, date);\ncreate index if not exists idx_appointments_date     on appointments(business_id, date, status);\n\ncreate trigger set_updated_at_appointments\n  before update on appointments\n  for each row execute function update_updated_at();\n\nalter table appointments enable row level security;\n\ncreate policy \"comercio gestiona appointments\"\n  on appointments for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\n\ncreate policy \"api inserta appointments\"\n  on appointments for insert with check (true);\n\n-- Habilitar realtime para appointments\nalter publication supabase_realtime add table appointments;\nalter publication supabase_realtime add table leads;\n"

files["app/admin/onboarding/page.tsx"] = "// app/admin/onboarding/page.tsx\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { slugify } from '@/lib/utils'\nimport { VERTICAL_LIST, type VerticalType } from '@/lib/verticals'\nimport { Check, ChevronRight, Zap, Store } from 'lucide-react'\nimport { cn } from '@/lib/utils'\n\nexport default function OnboardingPage() {\n  const router = useRouter()\n  const supabase = createClient()\n\n  const [step,       setStep]       = useState<'vertical' | 'info'>('vertical')\n  const [vertical,   setVertical]   = useState<VerticalType | null>(null)\n  const [name,       setName]       = useState('')\n  const [whatsapp,   setWhatsapp]   = useState('')\n  const [currency,   setCurrency]   = useState('UYU')\n  const [loading,    setLoading]    = useState(false)\n  const [error,      setError]      = useState<string | null>(null)\n\n  const selectedConfig = VERTICAL_LIST.find(v => v.key === vertical)\n\n  async function createBusiness(useDemo = false) {\n    setLoading(true); setError(null)\n    try {\n      const { data: { user } } = await supabase.auth.getUser()\n      if (!user) throw new Error('No autenticado')\n\n      const bizName = useDemo ? 'Mi Comercio Demo' : name.trim()\n      let slug = slugify(bizName)\n      const { data: existing } = await supabase\n        .from('businesses').select('id').eq('slug', slug).maybeSingle()\n      if (existing) slug = slug + '-' + Math.random().toString(36).slice(2, 5)\n\n      const { data: biz, error: bizErr } = await supabase\n        .from('businesses')\n        .insert({\n          name: bizName,\n          slug,\n          whatsapp: whatsapp.replace(/\\D/g, '') || null,\n          currency,\n          plan: 'pro',\n          active: true,\n          subscription_status: 'trial',\n          vertical_type: vertical ?? 'general',\n          primary_color: selectedConfig?.color ?? '#000000',\n        })\n        .select('id').single()\n\n      if (bizErr) throw bizErr\n\n      await supabase.from('profiles')\n        .upsert({ user_id: user.id, business_id: biz.id, role: 'owner' })\n\n      router.push('/admin')\n      router.refresh()\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n    } finally { setLoading(false) }\n  }\n\n  return (\n    <div className=\"min-h-screen flex items-center justify-center p-4\"\n      style={{ background: '#F7F9FC' }}>\n      <div className=\"w-full max-w-2xl\">\n\n        {/* Logo */}\n        <div className=\"text-center mb-8\">\n          <div className=\"inline-flex items-center gap-2.5 mb-4\">\n            <svg width=\"36\" height=\"36\" viewBox=\"0 0 40 40\" fill=\"none\">\n              <rect width=\"40\" height=\"40\" rx=\"10\" fill=\"#1565FF\"/>\n              <path d=\"M10 10L10 30L14 30L14 22L22 22L22 18L14 18L14 14L24 14L24 10Z\" fill=\"white\" opacity=\"0.95\"/>\n              <path d=\"M20 14L20 26L24 26L24 22C27 22 30 20 30 18C30 16 27 14 24 14Z\" fill=\"white\" opacity=\"0.7\"/>\n            </svg>\n            <span className=\"font-bold text-xl text-gray-900\">FyP Studio</span>\n          </div>\n          <h1 className=\"text-2xl font-bold text-gray-900 tracking-tight\">\n            {step === 'vertical' ? 'Elegí tu rubro' : 'Datos de tu negocio'}\n          </h1>\n          <p className=\"text-sm text-gray-400 mt-1\">\n            {step === 'vertical'\n              ? 'El sistema se adapta automáticamente a tu tipo de negocio'\n              : `Configurando para ${selectedConfig?.label}`\n            }\n          </p>\n        </div>\n\n        {/* STEP 1: Elegir vertical */}\n        {step === 'vertical' && (\n          <div className=\"space-y-4\">\n            <div className=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3\">\n              {VERTICAL_LIST.map(v => (\n                <button\n                  key={v.key}\n                  onClick={() => setVertical(v.key)}\n                  className={cn(\n                    'relative flex flex-col items-center gap-2 rounded-2xl border-2 p-4',\n                    'transition-all duration-150 active:scale-[0.97] text-left',\n                    vertical === v.key\n                      ? 'border-transparent shadow-lg'\n                      : 'border-gray-200 bg-white hover:border-gray-300 hover:shadow-sm'\n                  )}\n                  style={vertical === v.key ? {\n                    background: v.accentColor,\n                    borderColor: v.color,\n                  } : {}}\n                >\n                  {/* Check */}\n                  {vertical === v.key && (\n                    <div className=\"absolute top-2.5 right-2.5 h-5 w-5 rounded-full\n                                    flex items-center justify-center\"\n                      style={{ background: v.color }}>\n                      <Check size={11} className=\"text-white\" />\n                    </div>\n                  )}\n\n                  <span className=\"text-3xl\">{v.emoji}</span>\n                  <div className=\"text-center\">\n                    <p className=\"text-sm font-semibold text-gray-900\">{v.label}</p>\n                    <p className=\"text-[10px] text-gray-400 mt-0.5 leading-tight hidden sm:block\">\n                      {v.examples.slice(0, 2).join(', ')}\n                    </p>\n                  </div>\n\n                  {/* Color accent */}\n                  {vertical === v.key && (\n                    <div className=\"w-8 h-1 rounded-full mt-0.5\"\n                      style={{ background: v.color }} />\n                  )}\n                </button>\n              ))}\n            </div>\n\n            {/* Preview del vertical seleccionado */}\n            {selectedConfig && (\n              <div className=\"rounded-2xl border p-4 animate-fade-in\"\n                style={{ borderColor: selectedConfig.color + '33', background: selectedConfig.accentColor }}>\n                <div className=\"flex items-start gap-3\">\n                  <span className=\"text-2xl\">{selectedConfig.emoji}</span>\n                  <div className=\"flex-1 min-w-0\">\n                    <p className=\"font-semibold text-gray-900\">{selectedConfig.label}</p>\n                    <p className=\"text-xs text-gray-600 mt-0.5\">{selectedConfig.description}</p>\n                    <div className=\"flex flex-wrap gap-1.5 mt-2\">\n                      {selectedConfig.examples.map(ex => (\n                        <span key={ex} className=\"rounded-full px-2 py-0.5 text-[10px] font-medium text-white\"\n                          style={{ background: selectedConfig.color }}>\n                          {ex}\n                        </span>\n                      ))}\n                    </div>\n                    {/* Features */}\n                    <div className=\"flex flex-wrap gap-3 mt-3\">\n                      {selectedConfig.features.hasDelivery && (\n                        <span className=\"text-xs text-gray-500\">🛵 Delivery</span>\n                      )}\n                      {selectedConfig.features.hasBooking && (\n                        <span className=\"text-xs text-gray-500\">📅 Reservas</span>\n                      )}\n                      {selectedConfig.features.hasVariants && (\n                        <span className=\"text-xs text-gray-500\">🎨 Variantes</span>\n                      )}\n                      {selectedConfig.features.hasStock && (\n                        <span className=\"text-xs text-gray-500\">📦 Stock</span>\n                      )}\n                      {selectedConfig.features.hasCRM && (\n                        <span className=\"text-xs text-gray-500\">👥 CRM</span>\n                      )}\n                      {selectedConfig.features.hasMap && (\n                        <span className=\"text-xs text-gray-500\">🗺️ Mapa</span>\n                      )}\n                    </div>\n                  </div>\n                </div>\n              </div>\n            )}\n\n            <div className=\"flex gap-3\">\n              <button\n                onClick={() => vertical && setStep('info')}\n                disabled={!vertical}\n                className=\"flex-1 flex items-center justify-center gap-2 rounded-2xl py-3.5\n                           text-sm font-semibold text-white transition-all active:scale-[0.98]\n                           disabled:opacity-40 disabled:cursor-not-allowed\"\n                style={{ background: selectedConfig?.color ?? '#1565FF' }}\n              >\n                Continuar <ChevronRight size={16} />\n              </button>\n            </div>\n          </div>\n        )}\n\n        {/* STEP 2: Datos del negocio */}\n        {step === 'info' && selectedConfig && (\n          <div className=\"space-y-4\">\n            {/* Back */}\n            <button onClick={() => setStep('vertical')}\n              className=\"flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 transition-colors\">\n              ← Cambiar rubro\n            </button>\n\n            {/* Vertical badge */}\n            <div className=\"flex items-center gap-2 rounded-xl px-4 py-2.5 w-fit\"\n              style={{ background: selectedConfig.accentColor, border: `1px solid ${selectedConfig.color}33` }}>\n              <span className=\"text-lg\">{selectedConfig.emoji}</span>\n              <span className=\"text-sm font-semibold\" style={{ color: selectedConfig.color }}>\n                {selectedConfig.label}\n              </span>\n            </div>\n\n            {/* Formulario */}\n            <div className=\"bg-white rounded-2xl border border-gray-200 p-5 space-y-4\">\n              <div>\n                <label className=\"field-label\">\n                  Nombre del negocio <span className=\"text-red-400\">*</span>\n                </label>\n                <input type=\"text\" required value={name} onChange={e => setName(e.target.value)}\n                  placeholder={`Ej: ${selectedConfig.examples[0]}`}\n                  className=\"input-base\" />\n              </div>\n\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div>\n                  <label className=\"field-label\">WhatsApp</label>\n                  <input type=\"text\" value={whatsapp} onChange={e => setWhatsapp(e.target.value)}\n                    placeholder=\"59899123456\" className=\"input-base\" inputMode=\"numeric\" />\n                </div>\n                <div>\n                  <label className=\"field-label\">Moneda</label>\n                  <select value={currency} onChange={e => setCurrency(e.target.value)}\n                    className=\"input-base\">\n                    {['UYU','ARS','CLP','COP','MXN','USD','BRL'].map(c => (\n                      <option key={c} value={c}>{c}</option>\n                    ))}\n                  </select>\n                </div>\n              </div>\n            </div>\n\n            {error && (\n              <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n            )}\n\n            <div className=\"flex flex-col gap-3\">\n              <button\n                onClick={() => createBusiness(false)}\n                disabled={loading || !name.trim()}\n                className=\"w-full flex items-center justify-center gap-2 rounded-2xl py-4\n                           text-sm font-semibold text-white disabled:opacity-40\n                           transition-all active:scale-[0.98]\"\n                style={{ background: selectedConfig.color }}\n              >\n                {loading ? 'Creando...' : `Crear mi ${selectedConfig.label.toLowerCase()} →`}\n              </button>\n\n              <button\n                onClick={() => { setVertical(vertical ?? 'general'); createBusiness(true) }}\n                disabled={loading}\n                className=\"w-full flex items-center justify-center gap-2 rounded-2xl py-3\n                           text-sm font-medium text-gray-600 border border-gray-200 bg-white\n                           hover:bg-gray-50 disabled:opacity-40 transition-all\"\n              >\n                <Zap size={14} /> Empezar con demo rápido\n              </button>\n            </div>\n          </div>\n        )}\n      </div>\n    </div>\n  )\n}\n"

files["components/admin/AdminShell.tsx"] = "// components/admin/AdminShell.tsx\n// Layout principal con soporte completo mobile + desktop + verticales\n'use client'\nimport { useState } from 'react'\nimport Link from 'next/link'\nimport { usePathname, useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  LayoutDashboard, ShoppingBag, Package, Users, Settings,\n  Sparkles, LogOut, Tag, ExternalLink, Crown, Layers, Truck,\n  Menu, X, ChevronRight, MoreHorizontal, Target,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport { getVertical, getNavItems, type VerticalType } from '@/lib/verticals'\nimport type { Business } from '@/types'\n\n// Mapa de icon name → componente\nconst ICON_MAP: Record<string, React.ElementType> = {\n  LayoutDashboard, ShoppingBag, Package, Users, Settings,\n  Sparkles, Tag, Layers, Truck, Target,\n}\n\nfunction FypLogo({ size = 32 }: { size?: number }) {\n  return (\n    <svg width={size} height={size} viewBox=\"0 0 40 40\" fill=\"none\">\n      <rect width=\"40\" height=\"40\" rx=\"10\" fill=\"#1565FF\"/>\n      <path d=\"M10 10L10 30L14 30L14 22L22 22L22 18L14 18L14 14L24 14L24 10Z\" fill=\"white\" opacity=\"0.95\"/>\n      <path d=\"M20 14L20 26L24 26L24 22C27 22 30 20 30 18C30 16 27 14 24 14Z\" fill=\"white\" opacity=\"0.7\"/>\n    </svg>\n  )\n}\n\nfunction NavItem({\n  href, label, icon: iconName, exact, onClick, verticalColor,\n}: {\n  href: string; label: string; icon: string; exact?: boolean\n  onClick?: () => void; verticalColor: string\n}) {\n  const pathname = usePathname()\n  const isActive = exact ? pathname === href : pathname.startsWith(href)\n  const Icon = ICON_MAP[iconName] ?? Package\n\n  return (\n    <Link href={href} onClick={onClick}\n      className={cn(\n        'flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition-all',\n        isActive ? 'text-white' : 'text-gray-400 hover:text-white hover:bg-white/5'\n      )}\n      style={isActive ? {\n        background: `linear-gradient(90deg,${verticalColor}22,${verticalColor}0a)`,\n        borderLeft: `3px solid ${verticalColor}`,\n        paddingLeft: '9px',\n      } : {}}\n    >\n      <Icon size={15} style={isActive ? { color: verticalColor } : {}} />\n      <span className=\"flex-1\">{label}</span>\n      {isActive && <ChevronRight size={12} style={{ color: verticalColor, opacity: 0.6 }} />}\n    </Link>\n  )\n}\n\n// ── Sidebar Desktop ───────────────────────────────────────────\nfunction Sidebar({ business, userEmail, verticalColor, navItems }: {\n  business: Business | null; userEmail: string\n  verticalColor: string; navItems: ReturnType<typeof getNavItems>\n}) {\n  const router = useRouter()\n  const supabase = createClient()\n  const vertical = getVertical(business?.vertical_type)\n\n  async function handleLogout() {\n    await supabase.auth.signOut()\n    router.push('/auth/login')\n    router.refresh()\n  }\n\n  return (\n    <aside\n      className=\"hidden lg:flex w-[220px] flex-col h-full shrink-0\"\n      style={{ background: '#0B1929', borderRight: '1px solid rgba(255,255,255,0.06)' }}\n    >\n      {/* Logo + vertical */}\n      <div className=\"px-5 py-5 border-b\" style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n        <div className=\"flex items-center gap-3\">\n          <FypLogo size={34} />\n          <div>\n            <p className=\"text-white font-bold text-sm tracking-tight\">FyP Studio</p>\n            <div className=\"flex items-center gap-1.5 mt-0.5\">\n              <span className=\"text-sm\">{vertical.emoji}</span>\n              <p className=\"text-[11px] truncate max-w-[100px]\" style={{ color: verticalColor }}>\n                {business?.name ?? vertical.label}\n              </p>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* Dashboard link */}\n      <div className=\"px-3 pt-3\">\n        <NavItem href=\"/admin\" label=\"Dashboard\" icon=\"LayoutDashboard\"\n          exact verticalColor={verticalColor} />\n      </div>\n\n      {/* Nav items del vertical */}\n      <nav className=\"flex-1 px-3 pt-1 space-y-0.5 overflow-y-auto pb-2\">\n        {navItems.map(item => (\n          <NavItem key={item.href} href={item.href} label={item.label}\n            icon={item.icon} exact={item.exact} verticalColor={verticalColor} />\n        ))}\n      </nav>\n\n      {/* Plan badge */}\n      {(business?.plan === 'pro' || business?.plan === 'premium') && (\n        <div className=\"mx-3 mb-3 rounded-xl p-3\"\n          style={{ background: `${verticalColor}18`, border: `1px solid ${verticalColor}33` }}>\n          <div className=\"flex items-center gap-2 mb-0.5\">\n            <Crown size={12} className=\"text-yellow-400\" />\n            <span className=\"text-xs font-bold text-white capitalize\">{business.plan}</span>\n          </div>\n          <p className=\"text-[10px] text-gray-400\">Más funciones activas</p>\n        </div>\n      )}\n\n      {/* Footer */}\n      <div className=\"px-3 pb-4 pt-2 border-t space-y-0.5\"\n        style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n        {business?.slug && (\n          <Link href={`/store/${business.slug}`} target=\"_blank\"\n            className=\"flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                       hover:text-white hover:bg-white/5 transition-all\">\n            <ExternalLink size={14} /> Ver tienda\n          </Link>\n        )}\n        <button onClick={handleLogout}\n          className=\"w-full flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                     hover:text-red-400 hover:bg-red-500/10 transition-all\">\n          <LogOut size={14} /> Salir\n        </button>\n        <p className=\"px-3 pt-1 text-[10px] truncate\" style={{ color: '#374151' }}>{userEmail}</p>\n      </div>\n    </aside>\n  )\n}\n\n// ── Mobile Drawer ─────────────────────────────────────────────\nfunction MobileDrawer({ open, onClose, business, userEmail, verticalColor, navItems }: {\n  open: boolean; onClose: () => void; business: Business | null\n  userEmail: string; verticalColor: string; navItems: ReturnType<typeof getNavItems>\n}) {\n  const router = useRouter()\n  const supabase = createClient()\n  const vertical = getVertical(business?.vertical_type)\n\n  async function handleLogout() {\n    await supabase.auth.signOut()\n    router.push('/auth/login')\n    router.refresh()\n  }\n\n  return (\n    <>\n      {/* Overlay */}\n      <div onClick={onClose}\n        className={cn(\n          'fixed inset-0 z-40 bg-black/60 backdrop-blur-sm transition-opacity duration-300 lg:hidden',\n          open ? 'opacity-100' : 'opacity-0 pointer-events-none'\n        )}\n      />\n      {/* Drawer */}\n      <div\n        className=\"fixed top-0 left-0 bottom-0 z-50 w-72 flex flex-col transition-transform duration-300 ease-out lg:hidden\"\n        style={{\n          background: '#0B1929',\n          transform: open ? 'translateX(0)' : 'translateX(-100%)',\n          boxShadow: open ? '4px 0 32px rgba(0,0,0,0.4)' : 'none',\n        }}\n      >\n        {/* Header */}\n        <div className=\"flex items-center justify-between px-5 py-4 border-b\"\n          style={{ borderColor: 'rgba(255,255,255,0.08)' }}>\n          <div className=\"flex items-center gap-3\">\n            <FypLogo size={32} />\n            <div>\n              <p className=\"text-white font-bold text-sm\">FyP Studio</p>\n              <div className=\"flex items-center gap-1 mt-0.5\">\n                <span className=\"text-xs\">{vertical.emoji}</span>\n                <p className=\"text-[10px]\" style={{ color: verticalColor }}>\n                  {business?.name ?? vertical.label}\n                </p>\n              </div>\n            </div>\n          </div>\n          <button onClick={onClose}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl text-gray-400\n                       hover:bg-white/10 hover:text-white transition-all\">\n            <X size={18} />\n          </button>\n        </div>\n\n        {/* Nav */}\n        <nav className=\"flex-1 px-3 pt-4 space-y-0.5 overflow-y-auto pb-4\">\n          <NavItem href=\"/admin\" label=\"Dashboard\" icon=\"LayoutDashboard\"\n            exact onClick={onClose} verticalColor={verticalColor} />\n          {navItems.map(item => (\n            <NavItem key={item.href} {...item} onClick={onClose} verticalColor={verticalColor} />\n          ))}\n        </nav>\n\n        {/* Plan */}\n        {(business?.plan === 'pro' || business?.plan === 'premium') && (\n          <div className=\"mx-3 mb-3 rounded-xl p-3\"\n            style={{ background: `${verticalColor}18`, border: `1px solid ${verticalColor}33` }}>\n            <div className=\"flex items-center gap-2 mb-0.5\">\n              <Crown size={12} className=\"text-yellow-400\" />\n              <span className=\"text-xs font-bold text-white capitalize\">{business.plan}</span>\n            </div>\n            <p className=\"text-[10px] text-gray-400\">Más funciones activas</p>\n          </div>\n        )}\n\n        {/* Footer */}\n        <div className=\"px-3 pb-8 pt-3 border-t space-y-0.5\"\n          style={{ borderColor: 'rgba(255,255,255,0.06)' }}>\n          {business?.slug && (\n            <Link href={`/store/${business.slug}`} target=\"_blank\" onClick={onClose}\n              className=\"flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                         hover:text-white hover:bg-white/5 transition-all\">\n              <ExternalLink size={14} /> Ver tienda\n            </Link>\n          )}\n          <button onClick={handleLogout}\n            className=\"w-full flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-gray-400\n                       hover:text-red-400 hover:bg-red-500/10 transition-all\">\n            <LogOut size={14} /> Salir\n          </button>\n          <p className=\"px-3 pt-2 text-[10px] truncate\" style={{ color: '#374151' }}>{userEmail}</p>\n        </div>\n      </div>\n    </>\n  )\n}\n\n// ── Mobile Top Bar ────────────────────────────────────────────\nfunction MobileTopBar({ business, userEmail, onMenuOpen, verticalColor }: {\n  business: Business | null; userEmail: string\n  onMenuOpen: () => void; verticalColor: string\n}) {\n  const vertical = getVertical(business?.vertical_type)\n  return (\n    <header className=\"lg:hidden h-14 shrink-0 flex items-center justify-between px-4 border-b\"\n      style={{ background: '#0B1929', borderColor: 'rgba(255,255,255,0.08)' }}>\n      <button onClick={onMenuOpen}\n        className=\"flex h-9 w-9 items-center justify-center rounded-xl text-gray-400\n                   hover:bg-white/10 hover:text-white transition-all\">\n        <Menu size={20} />\n      </button>\n      <div className=\"flex items-center gap-2\">\n        <FypLogo size={26} />\n        <span className=\"text-white font-bold text-sm\">FyP Studio</span>\n      </div>\n      <div className=\"h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-bold\"\n        style={{ background: `linear-gradient(135deg,${verticalColor},${verticalColor}99)` }}>\n        {userEmail.slice(0, 1).toUpperCase()}\n      </div>\n    </header>\n  )\n}\n\n// ── Bottom Nav Mobile ─────────────────────────────────────────\nfunction BottomNav({ onMoreOpen, navItems, verticalColor }: {\n  onMoreOpen: () => void\n  navItems: ReturnType<typeof getNavItems>\n  verticalColor: string\n}) {\n  const pathname = usePathname()\n  // Tomar los primeros 4 del vertical\n  const mainItems = [\n    { href: '/admin', label: 'Inicio', icon: 'LayoutDashboard', exact: true },\n    ...navItems.slice(0, 3),\n  ].slice(0, 4)\n\n  return (\n    <nav className=\"lg:hidden fixed bottom-0 left-0 right-0 z-30 flex items-center border-t\"\n      style={{\n        background: '#0B1929',\n        borderColor: 'rgba(255,255,255,0.08)',\n        paddingBottom: 'env(safe-area-inset-bottom)',\n      }}>\n      {mainItems.map(({ href, label, icon: iconName, exact }) => {\n        const isActive = exact ? pathname === href : pathname.startsWith(href)\n        const Icon = ICON_MAP[iconName] ?? Package\n        return (\n          <Link key={href} href={href}\n            className=\"flex-1 flex flex-col items-center gap-1 py-2.5 transition-all\">\n            <div className={cn(\n              'flex items-center justify-center h-7 w-7 rounded-xl transition-all',\n              isActive ? 'bg-blue-500/20' : ''\n            )}>\n              <Icon size={18} style={isActive ? { color: verticalColor } : { color: '#6B7280' }} />\n            </div>\n            <span className=\"text-[10px] font-medium\"\n              style={{ color: isActive ? verticalColor : '#6B7280' }}>\n              {label.length > 8 ? label.slice(0, 7) + '…' : label}\n            </span>\n          </Link>\n        )\n      })}\n\n      {/* Más */}\n      <button onClick={onMoreOpen}\n        className=\"flex-1 flex flex-col items-center gap-1 py-2.5\">\n        <div className=\"flex items-center justify-center h-7 w-7 rounded-xl\">\n          <MoreHorizontal size={18} style={{ color: '#6B7280' }} />\n        </div>\n        <span className=\"text-[10px] font-medium\" style={{ color: '#6B7280' }}>Más</span>\n      </button>\n    </nav>\n  )\n}\n\n// ── Desktop Top Bar ───────────────────────────────────────────\nfunction DesktopTopBar({ userEmail, verticalColor }: { userEmail: string; verticalColor: string }) {\n  return (\n    <header className=\"hidden lg:flex h-14 shrink-0 items-center justify-end px-6\n                       bg-white border-b border-gray-100\">\n      <div className=\"h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-bold\"\n        style={{ background: `linear-gradient(135deg,${verticalColor},${verticalColor}99)` }}>\n        {userEmail.slice(0, 1).toUpperCase()}\n      </div>\n    </header>\n  )\n}\n\n// ── SHELL PRINCIPAL ───────────────────────────────────────────\nexport default function AdminShell({ children, business, userEmail, suspended }: {\n  children: React.ReactNode; business: Business | null\n  userEmail: string; suspended: boolean\n}) {\n  const [drawerOpen, setDrawerOpen] = useState(false)\n\n  const vertical = getVertical(business?.vertical_type)\n  const verticalColor = business?.primary_color ?? vertical.color\n  const navItems = getNavItems((business?.vertical_type as VerticalType) ?? 'general')\n\n  return (\n    <div className=\"flex h-screen overflow-hidden\" style={{ background: '#F7F9FC' }}>\n\n      {/* Desktop sidebar */}\n      <Sidebar business={business} userEmail={userEmail}\n        verticalColor={verticalColor} navItems={navItems} />\n\n      {/* Mobile drawer */}\n      <MobileDrawer open={drawerOpen} onClose={() => setDrawerOpen(false)}\n        business={business} userEmail={userEmail}\n        verticalColor={verticalColor} navItems={navItems} />\n\n      {/* Contenido */}\n      <div className=\"flex-1 flex flex-col overflow-hidden min-w-0\">\n        <MobileTopBar business={business} userEmail={userEmail}\n          onMenuOpen={() => setDrawerOpen(true)} verticalColor={verticalColor} />\n        <DesktopTopBar userEmail={userEmail} verticalColor={verticalColor} />\n\n        {suspended && (\n          <div className=\"bg-red-500 text-white text-xs text-center py-2 px-4 font-medium shrink-0\">\n            ⚠️ Suscripción suspendida — contactá soporte\n          </div>\n        )}\n\n        <main className=\"flex-1 overflow-y-auto\">\n          <div className=\"p-4 lg:p-8 pb-24 lg:pb-8 max-w-6xl mx-auto\">\n            {children}\n          </div>\n        </main>\n\n        <BottomNav onMoreOpen={() => setDrawerOpen(true)}\n          navItems={navItems} verticalColor={verticalColor} />\n      </div>\n    </div>\n  )\n}\n"

files["app/admin/settings/VerticalSelector.tsx"] = "// app/admin/settings/VerticalSelector.tsx\n// Widget para cambiar el vertical desde Settings\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { VERTICAL_LIST, type VerticalType } from '@/lib/verticals'\nimport { Check, Loader2 } from 'lucide-react'\nimport { cn } from '@/lib/utils'\n\nexport default function VerticalSelector({\n  businessId,\n  currentVertical,\n}: {\n  businessId: string\n  currentVertical: VerticalType\n}) {\n  const router = useRouter()\n  const [selected, setSelected] = useState<VerticalType>(currentVertical)\n  const [saving,   setSaving]   = useState(false)\n  const [saved,    setSaved]    = useState(false)\n\n  async function handleSave() {\n    if (selected === currentVertical) return\n    setSaving(true)\n    const res = await fetch('/api/business/settings', {\n      method: 'PATCH',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ vertical_type: selected }),\n    })\n    if (res.ok) {\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2000)\n      router.refresh()\n    }\n    setSaving(false)\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2\">\n        {VERTICAL_LIST.map(v => (\n          <button key={v.key} onClick={() => setSelected(v.key as VerticalType)}\n            className={cn(\n              'relative flex flex-col items-center gap-1.5 rounded-xl border-2 p-3 transition-all text-center',\n              selected === v.key ? 'shadow-sm' : 'border-gray-100 bg-gray-50 hover:border-gray-200'\n            )}\n            style={selected === v.key ? {\n              borderColor: v.color,\n              background: v.accentColor,\n            } : {}}\n          >\n            {selected === v.key && (\n              <div className=\"absolute top-1.5 right-1.5 h-4 w-4 rounded-full flex items-center justify-center\"\n                style={{ background: v.color }}>\n                <Check size={9} className=\"text-white\" />\n              </div>\n            )}\n            <span className=\"text-xl\">{v.emoji}</span>\n            <p className=\"text-xs font-semibold text-gray-900\">{v.label}</p>\n          </button>\n        ))}\n      </div>\n\n      {selected !== currentVertical && (\n        <div className=\"flex items-center gap-3 animate-fade-in\">\n          <button onClick={handleSave} disabled={saving}\n            className=\"flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-semibold\n                       text-white disabled:opacity-40\"\n            style={{ background: VERTICAL_LIST.find(v=>v.key===selected)?.color ?? '#1565FF' }}>\n            {saving ? <Loader2 size={14} className=\"animate-spin\"/> : null}\n            {saving ? 'Guardando...' : saved ? '✓ Guardado' : 'Cambiar a ' + VERTICAL_LIST.find(v=>v.key===selected)?.label}\n          </button>\n          <p className=\"text-xs text-gray-400\">\n            ⚠️ Cambia el menú y los módulos del panel\n          </p>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/api/business/settings/route.ts"] = "// app/api/business/settings/route.ts\nimport { createClient } from '@/lib/supabase/server'\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { NextResponse } from 'next/server'\n\nexport async function PATCH(req: Request) {\n  try {\n    const supabase = await createClient()\n    const { data: { user }, error: authError } = await supabase.auth.getUser()\n    if (authError || !user)\n      return NextResponse.json({ error: 'No autorizado' }, { status: 401 })\n\n    const { data: profile } = await supabase\n      .from('profiles')\n      .select('business_id')\n      .eq('user_id', user.id)\n      .single()\n\n    if (!profile?.business_id)\n      return NextResponse.json({ error: 'Sin negocio' }, { status: 403 })\n\n    const body = await req.json()\n\n    // Campos permitidos — solo los que vienen en el body\n    const payload: Record<string, unknown> = {}\n\n    if (body.name !== undefined)            payload.name            = (body.name ?? '').trim() || null\n    if (body.whatsapp !== undefined)        payload.whatsapp        = (body.whatsapp ?? '').replace(/[^\\d]/g, '') || null\n    if (body.address !== undefined)         payload.address         = (body.address ?? '').trim() || null\n    if (body.currency !== undefined)        payload.currency        = body.currency\n    if (body.primary_color !== undefined)   payload.primary_color   = body.primary_color\n    if (body.secondary_color !== undefined) payload.secondary_color = body.secondary_color\n    if (body.logo_url !== undefined)        payload.logo_url        = (body.logo_url ?? '').trim() || null\n    if (body.banner_url !== undefined)      payload.banner_url      = (body.banner_url ?? '').trim() || null\n    if (body.instagram !== undefined)       payload.instagram       = (body.instagram ?? '').trim().replace(/^@/, '') || null\n    if (body.tiktok !== undefined)          payload.tiktok          = (body.tiktok ?? '').trim().replace(/^@/, '') || null\n    if (body.website !== undefined)         payload.website         = (body.website ?? '').trim() || null\n    if (body.vertical_type !== undefined)   payload.vertical_type   = body.vertical_type\n\n    if (Object.keys(payload).length === 0)\n      return NextResponse.json({ error: 'Sin campos para actualizar' }, { status: 400 })\n\n    const service = createServiceClient()\n    const { data, error } = await service\n      .from('businesses')\n      .update(payload)\n      .eq('id', profile.business_id)\n      .select('id, name, whatsapp, slug, vertical_type')\n      .single()\n\n    if (error) {\n      console.error('[settings PATCH]', error)\n      return NextResponse.json({ error: error.message }, { status: 500 })\n    }\n\n    return NextResponse.json({ ok: true, business: data })\n  } catch (err) {\n    console.error('[settings PATCH] unexpected:', err)\n    return NextResponse.json({ error: 'Error interno' }, { status: 500 })\n  }\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  ✅ '+p)
}
